import {randomUUID} from 'node:crypto';
import {countries,nickname,schoolCode,seedStudents,MockAiStartifyClient,type AiStartifyClient,assertPublic,points,funnel,cpa,attribute,compliance,messageVariants,csv,rank,balance,levelFor,redeemBalance,fraudCheck,challengeScore,rubricScore,badges,validateTeam,parseNicknameCsv,codeActive,activationHealth} from './index';
export type Row=Record<string,any>;
type Delegate={findMany(args?:any):Promise<Row[]>;findUnique(args:any):Promise<Row|null>;findFirst(args?:any):Promise<Row|null>;count(args?:any):Promise<number>;create(args:any):Promise<Row>;createMany(args:any):Promise<any>;update(args:any):Promise<Row>;updateMany(args:any):Promise<any>};
export type Database=Record<string,Delegate>&{$transaction:<T>(fn:(tx:Database)=>Promise<T>)=>Promise<T>};
const uid=()=>randomUUID();const now=()=>new Date();const date=(day:number)=>new Date(Date.UTC(2026,10,1+day));
export type Field={name:string;label:string;type?:string;options?:string[];value?:string|number;required?:boolean;min?:number;max?:number;hint?:string};
export type Form={title:string;op:string;fields:Field[];hidden?:Row;button?:string};
export type View={app:string;path:string;role:string;roles:string[];title:string;subtitle:string;nav:{href:string;label:string}[];metrics:{label:string;value:string|number;note?:string}[];tables:{title:string;columns:string[];rows:(string|number)[][]}[];forms:Form[];cards:{title:string;text:string;href?:string;tag?:string}[];chart?:{label:string;value:number}[];extra?:Row;};
const names:Record<string,string>={'growth-engine':'Growth engine','ambassador-platform':'Ambassador network','challenge-platform':'Startup challenges','school-portal':'School studio','school-league':'School league'};
const menus:Record<string,[string,string][]>= {
 'growth-engine':[['/campaigns','Кампании|Campaigns'],['/campaigns/new','Новая кампания|New campaign'],['/analytics','Аналитика|Analytics'],['/compliance','Безопасность|Compliance']],
 'ambassador-platform':[['/dashboard','Обзор|Dashboard'],['/join','Стать амбассадором|Join'],['/tasks','Задания|Tasks'],['/rewards','Награды|Rewards'],['/leaderboard','Рейтинг|Leaderboard'],['/admin','Управление|Admin']],
 'challenge-platform':[['/challenges','Челленджи|Challenges'],['/judge','Оценить|Judge'],['/admin','Управление|Admin'],['/showcase','Финалисты|Showcase']],
 'school-portal':[['/dashboard','Обзор|Dashboard'],['/register','Добавить школу|Register school'],['/lesson-kit','Четыре занятия|Lesson kit'],['/reports','Отчёты|Reports'],['/partner','Партнёрства|Partners']],
 'school-league':[['/','Рейтинг|Leaderboard'],['/join','Найти школу|Join school'],['/card','Карточка основателя|Founder card'],['/admin','Сезоны|Seasons']]};
const roleMap:Record<string,string[]>={'growth-engine':['viewer','growth-manager'],'ambassador-platform':['visitor','ambassador','admin'],'challenge-platform':['student','teacher','judge','admin'],'school-portal':['teacher','partner-manager'],'school-league':['visitor','student','teacher']};
const field=(name:string,label:string,type='text',options?:string[],value?:string|number):Field=>({name,label,type,options,value,required:true});
const optionsCountry=()=>field('country','Страна|Country','select',countries.map(c=>c.code));
function required(d:Row,k:string){const s=String(d[k]??'').trim();if(!s||s.length>3000)throw new Error(`Required / Заполните: ${k}`);return s;}
function number(d:Row,k:string,min=0,max=1e6){const n=Number(d[k]);if(!Number.isFinite(n)||n<min||n>max)throw new Error(`Invalid / Недопустимое значение: ${k}`);return n;}
function choose(d:Row,k:string,values:string[]){const v=required(d,k);if(!values.includes(v))throw new Error(`Invalid ${k}`);return v;}
const publicText=(d:Row,k:string)=>{const s=required(d,k);assertPublic(s);return s;};
const add=(db:Database,model:string,data:Row)=>db[model].create({data});
const get=async(db:Database,model:string,id:string)=>{const row=await db[model].findUnique({where:{id}});if(!row)throw new Error('Record not found / Запись не найдена');return row;};
export function makeService(app:string,db:Database){
 const roles=roleMap[app];
 const platform:AiStartifyClient=new MockAiStartifyClient();
 async function seed(){if(app==='growth-engine'){
  if(await db.campaign.count())return;
  for(const key of ['adult','pii','mention'])await add(db,'complianceRule',{id:key,key,description:{adult:'Paid audiences must be 18+',pii:'No personal data or requests',mention:'Mention parent or teacher'}[key],enabled:true});
  for(let i=0;i<10;i++){const c={id:`campaign-${i}`,name:`Launch ${i+1}`,country:countries[i%6].code,audience:i%2?'parent':'teacher',channel:['instagram','telegram','youtube','email','school_chat'][i%5],language:i%3?'ru':'en',tone:'friendly',budgetUsd:100+i*25,minAge:18,status:i%3?'running':'ready',createdAt:date(i)};await add(db,'campaign',c);for(const v of messageVariants(c))await add(db,'messageVariant',{id:`v-${i}-${v.label}`,campaignId:c.id,...v});const link=await platform.createReferral(c.id,c.channel);await add(db,'referralLink',{id:`link-${i}`,campaignId:c.id,...link,utm:`utm_source=${c.channel}&utm_campaign=${c.id}`});for(let j=0;j<200;j++)await add(db,'trackedEvent',{id:`event-${i}-${j}`,linkCode:link.code,type:j<110?'visit':j<165?'registered':j<192?'started':'published',country:c.country,ts:date(j%12)});}
 }
 if(app==='ambassador-platform'){
  if(await db.ambassador.count())return;
  for(let i=0;i<20;i++){await add(db,'ambassador',{id:`amb-${i}`,nickname:nickname(i),country:countries[i%6].code,city:`City ${i%6+1}`,age18Confirmed:true,level:'Bronze',createdAt:date(i)});await add(db,'pointsLedger',{id:`ledger-${i}`,ambassadorId:`amb-${i}`,delta:i===0?180:i*90,reason:'Demo contribution',refType:'seed',refId:`seed-${i}`});await add(db,'referralLink',{id:`ref-${i}`,ambassadorId:`amb-${i}`,code:`AMB-${i+1}`});}
  for(let i=0;i<12;i++)await add(db,'task',{id:`task-${i}`,title:['Invite a school / Пригласите школу','Share club kit / Поделитесь набором','Host a webinar / Проведите вебинар'][i%3],type:['onboard_school','content','webinar','invite_students'][i%4],points:50+i*10,description:'Use public resources; never collect student personal data. / Используйте публичные материалы без данных учеников.',proofType:['link','text','number'][i%3]});
  for(let i=0;i<8;i++)await add(db,'reward',{id:`reward-${i}`,title:['Mentor session / Встреча с наставником','Workshop ticket / Билет на воркшоп','Demo certificate / Демосертификат','Club toolkit / Набор для клуба'][i%4],costPoints:100+i*50,stock:10});
  for(let i=0;i<4;i++)await add(db,'submission',{id:`submission-${i}`,taskId:`task-${i}`,ambassadorId:'amb-0',proof:'https://example.org/demo-proof',status:'pending'});
 }

 if(app==='challenge-platform'){
  if(await db.challenge.count())return;
  for(const key of ['First step','Published','Cross-border team','Streak'])await add(db,'badge',{id:key,key,title:key,description:key});
  for(let i=0;i<3;i++)await add(db,'challenge',{id:`challenge-${i}`,title:['Make school better / Сделайте школу лучше','Green neighborhood / Зелёный квартал','Ideas across borders / Идеи без границ'][i],theme:'AI for everyday impact / AI для полезных перемен',startAt:date(0),endAt:new Date('2027-02-01'),status:['open','judging','closed'][i],rubricJson:JSON.stringify(['Impact','Originality','Feasibility']),weightsJson:JSON.stringify({auto:.5,rubric:[.4,.3,.3]})});
  for(let i=0;i<18;i++){const teamId=`team-${i}`;await add(db,'team',{id:teamId,challengeId:`challenge-${i%3}`,name:`Orbit-${i+1}`,schoolCode:schoolCode(i%8),country:countries[i%6].code,createdAt:date(i)});for(let j=0;j<3;j++)await add(db,'teamMember',{id:`member-${i}-${j}`,teamId,studentRef:`stu-${i}-${j}`,nickname:nickname(i*3+j),country:countries[(i+j%2)%6].code});for(let day=0;day<3;day++)await add(db,'progressSnapshot',{id:`snapshot-${i}-${day}`,teamId,started:1+day,published:i%3===0?1:0,avgStage:3+day,ts:date(day)});for(let j=0;j<3;j++)await add(db,'judgeScore',{id:`judge-score-${i}-${j}`,teamId,judgeId:`judge-${j}`,criteriaJson:'[70,80,75]',total:75+i%5});await awardBadges(db,teamId);}
  const frozen=await challengeRanking(db,'challenge-2');await db.challenge.update({where:{id:'challenge-2'},data:{frozenJson:JSON.stringify(frozen)}});
 }

 if(app==='school-portal'){
  if(await db.school.count())return;
  for(let i=0;i<12;i++){const status=['active','pilot','lead','paused'][i%4];await add(db,'school',{id:`school-${i}`,name:`School ${i+1}`,country:countries[i%6].code,city:`City ${i%6+1}`,type:'secondary',status,consentConfirmed:i%4<2,createdAt:date(i)});await add(db,'teacher',{id:`teacher-${i}`,schoolId:`school-${i}`,displayName:`Mentor${i+1}`,role:'school-admin'});}
  for(let i=0;i<30;i++)await add(db,'classGroup',{id:`class-${i}`,schoolId:`school-${i%12}`,name:`Club ${i+1}`,gradeRange:'7–11',code:`CLUB-${String(i+1).padStart(3,'0')}`,active:i%12%4<2});
  const students=seedStudents(300,30);for(let i=0;i<students.length;i++){const s=students[i];await add(db,'studentEntry',{id:`entry-${i}`,classId:`class-${i%30}`,nickname:s.nickname,studentRef:s.studentRef,stage:s.stage,status:s.status});}
  const ru=['Найдите проблему','Проверьте идею','Создайте прототип','Расскажите о проекте'],en=['Find a problem','Validate the idea','Build a prototype','Tell your story'];for(let i=0;i<4;i++)await add(db,'lessonKit',{id:`lesson-${i}`,order:i+1,title:`${ru[i]}|${en[i]}`,objectives:['Назовите проблему и кому она мешает|Name a problem and who it affects','Сформулируйте гипотезу и проверьте её без сбора личных данных|Test a hypothesis without collecting personal data','Создайте простой макет и проверьте его с наставником|Build a small mockup and test it with a mentor','Опубликуйте безопасное описание и подготовьте питч|Publish a safe project description and prepare a pitch'][i],steps:'5 мин: обсуждение → 10 мин: пример → 20 мин: работа в команде → 10 мин: рефлексия|5 min: discuss → 10 min: example → 20 min: team work → 10 min: reflect',stageRange:['1–2','3–5','6–8','9–10'][i]});
 }

 if(app==='school-league'){
  if(await db.school.count())return;
  await add(db,'season',{id:'season-0',title:'Builders without borders / Создатели без границ',startAt:date(0),endAt:new Date('2027-02-01'),active:true,frozen:false});
  for(let i=0;i<20;i++){await add(db,'school',{id:`school-${i}`,slug:`school-${i}`,name:`School ${i+1}`,country:countries[i%6].code,city:`City ${i%8+1}`,code:schoolCode(i)});await add(db,'pointsSnapshot',{id:`season-0:school-${i}`,seasonId:'season-0',schoolId:`school-${i}`,started:0,published:0,points:0,ts:date(i)});}
  for(let i=0;i<400;i++){const schoolId=`school-${i%20}`;await add(db,'student',{id:`student-${i}`,schoolId,nickname:nickname(i),studentRef:`stu-${i}`});const published=i%3===0;await add(db,'project',{id:`project-${i}`,studentId:`student-${i}`,title:`eco-orbit-${i+1}`,idea:'A greener school, one small idea at a time / Сделаем школу зеленее вместе',status:published?'published':'started',passportId:`DEMO-${i+1}`,publishedAt:published?date(i%12):null,createdAt:date(i%12)});const snap=await db.pointsSnapshot.findFirst({where:{seasonId:'season-0',schoolId}});await db.pointsSnapshot.update({where:{id:snap!.id},data:{started:{increment:1},published:{increment:published?1:0},points:{increment:points(1,published?1:0)}}});}
 }

 // APP_SEEDS
 }
 async function growthMutate(op:string,d:Row,role:string){
  if(op==='event'){const code=required(d,'linkCode');if(!await db.referralLink.findUnique({where:{code}}))throw new Error('Unknown referral code');await add(db,'trackedEvent',{id:uid(),linkCode:code,type:choose(d,'type',['visit','registered','started','published']),country:choose(d,'country',countries.map(c=>c.code))});return {message:'Event attributed / Событие учтено'};}
  if(role!=='growth-manager')throw new Error('Sign in as growth-manager / Выберите роль growth-manager');
  if(op==='createCampaign'){const c={id:uid(),name:publicText(d,'name'),country:choose(d,'country',countries.map(c=>c.code)),audience:choose(d,'audience',['teacher','parent','ambassador','student']),channel:choose(d,'channel',['telegram','instagram','youtube','email','school_chat']),language:choose(d,'language',['ru','en']),tone:publicText(d,'tone'),budgetUsd:number(d,'budgetUsd'),minAge:number(d,'minAge',0,100)};const variants=messageVariants(c,process.env.LLM_PROVIDER??'mock');const checks=compliance({...c,text:variants.map(v=>v.text).join(' ')});if(checks.some(r=>r.level==='block'))throw new Error(checks.map(r=>r.reason).join('; '));const link=await platform.createReferral(c.id,c.channel);await db.$transaction(async tx=>{await add(tx,'campaign',{...c,status:'ready'});for(const v of variants)await add(tx,'messageVariant',{id:uid(),campaignId:c.id,...v});await add(tx,'referralLink',{id:uid(),campaignId:c.id,...link,utm:`utm_source=${c.channel}&utm_campaign=${c.id}&utm_medium=referral`});});return {redirect:`/campaigns/${c.id}`,message:'Campaign created / Кампания создана'};}
  if(op==='simulate'){const n=number(d,'n',1,1000);const links=await db.referralLink.findMany();for(let i=0;i<n;i++){const l=links[i%links.length];const c=await get(db,'campaign',l.campaignId);await add(db,'trackedEvent',{id:uid(),linkCode:l.code,type:['visit','registered','started','published'][i%4],country:c.country});}return {message:`+${n} demo events / демособытий`};}
  if(op==='rule'){const key=choose(d,'key',['mention']);await db.complianceRule.update({where:{key},data:{enabled:d.enabled==='true'}});return {message:'Rule updated / Правило обновлено'};}
  throw new Error('Unknown action');
 }
 async function growthView(v:View){const campaigns=await db.campaign.findMany({orderBy:{createdAt:'desc'}});const events=await db.trackedEvent.findMany();const links=await db.referralLink.findMany();const f=funnel(events as any);v.metrics=Object.entries(f).map(([label,value])=>({label,value}));v.chart=Object.entries(f).map(([label,value])=>({label,value}));
  if(v.path==='/campaigns/new'){v.forms.push({title:'Запустите следующую идею|Launch the next idea',op:'createCampaign',button:'Создать 3 варианта|Create 3 variants',fields:[field('name','Название|Campaign name'),optionsCountry(),field('audience','Аудитория|Audience','select',['parent','teacher','ambassador','student']),field('channel','Канал|Channel','select',['instagram','telegram','youtube','email','school_chat']),field('language','Язык сообщений|Message language','select',['ru','en']),field('tone','Тон|Tone','text',undefined,'friendly'),field('budgetUsd','Бюджет USD|Budget USD','number',undefined,100),field('minAge','Минимальный возраст аудитории|Minimum audience age','number',undefined,18)]});}
  else if(v.path.startsWith('/campaigns/')){const c=await get(db,'campaign',v.path.split('/')[2]);const variants=await db.messageVariant.findMany({where:{campaignId:c.id}});const l=links.find(l=>l.campaignId===c.id)!;const cf=funnel(attribute(events as any,l.code));v.title=c.name;v.cards=variants.map(r=>({title:`Вариант|Variant ${r.label}`,text:r.text,tag:r.label}));v.cards.push({title:'Ссылка с атрибуцией|Tracked referral',text:`${l.url}?${l.utm}`,href:`${l.url}?${l.utm}`});const ruleRows=await db.complianceRule.findMany();const checks=compliance({...c,text:variants.map(r=>r.text).join(' ')} as any,{adult:true,pii:true,mention:ruleRows.find(r=>r.key==='mention')?.enabled??true});v.tables.push({title:'Проверка безопасности|Compliance result',columns:['Статус|Status','Причина|Reason'],rows:checks.map(r=>[r.level,r.reason])});v.metrics=Object.entries(cf).map(([label,value])=>({label,value}));v.metrics.push({label:'CPA регистрации|Registration CPA',value:cpa(c.budgetUsd,cf.registered)?.toFixed(2)??'—'},{label:'CPA проекта|Published CPA',value:cpa(c.budgetUsd,cf.published)?.toFixed(2)??'—'});}
  else if(v.path==='/compliance'){const rules=await db.complianceRule.findMany();v.tables.push({title:'Правила|Rules',columns:['Правило|Rule','Включено|Enabled'],rows:rules.map(r=>[r.description,r.enabled?'✓':'—'])});v.cards.push({title:'Обязательная защита|Mandatory protection',text:'Проверки возраста и персональных данных всегда включены.|Age and personal data checks are always enforced.'});v.forms.push({title:'Рекомендация о наставнике|Mentor mention rule',op:'rule',fields:[field('enabled','Включено|Enabled','select',['true','false'])],hidden:{key:'mention'}});}
  else {v.tables.push({title:'Кампании|Campaigns',columns:['Кампания|Campaign','Страна|Country','Канал|Channel','Статус|Status','Бюджет|Budget','Открыть|Open'],rows:campaigns.map(c=>[c.name,c.country,c.channel,c.status,`$${c.budgetUsd}`,`/campaigns/${c.id}`])});if(v.path==='/analytics'){for(const dim of ['country','channel']){const rows=[...new Set(campaigns.map(c=>c[dim]))].map(key=>{const codes=links.filter(l=>campaigns.some(c=>c.id===l.campaignId&&c[dim]===key)).map(l=>l.code);const g=funnel(events.filter(e=>codes.includes(e.linkCode)) as any);return [key,g.visit,g.registered,g.started,g.published];});v.tables.push({title:dim==='country'?'По странам|By country':'По каналам|By channel',columns:[dim,'visit','registered','started','published'],rows});}const top=campaigns.map(c=>{const code=links.find(l=>l.campaignId===c.id)?.code;return {...c,name:String(c.name),...funnel(events.filter(e=>e.linkCode===code) as any)};}).sort((a,b)=>b.published-a.published).slice(0,3);v.tables.push({title:'Топ 3|Top 3',columns:['Кампания|Campaign','Опубликовано|Published'],rows:top.map(c=>[c.name,c.published])});}}
 }
 async function ambassadorMutate(op:string,d:Row,role:string){
  if(op==='join'){if(d.adult!=='true'||d.conduct!=='true')throw new Error('Confirm age 18+ and code of conduct / Подтвердите 18+ и правила программы');const id=uid();await db.$transaction(async tx=>{await add(tx,'ambassador',{id,nickname:publicText(d,'nickname'),country:choose(d,'country',countries.map(c=>c.code)),city:publicText(d,'city'),age18Confirmed:true});await add(tx,'referralLink',{id:uid(),ambassadorId:id,code:`AMB-${id.slice(0,8)}`});});return {message:'Welcome! Select your new ambassador in the dashboard / Выберите новый профиль в обзоре',redirect:'/dashboard?selection='+id};}
  const ambassadorId=String(d.ambassadorId??'amb-0');
  if(op==='simulate'){if(!['ambassador','admin'].includes(role))throw new Error('Select ambassador or admin role');const n=number(d,'n',1,100);const ref=await db.referralLink.findFirst({where:{ambassadorId}});if(!ref)throw new Error('Referral missing');const mock=new MockAiStartifyClient();const client:AiStartifyClient=mock;const events:Row[]=[];const off=client.subscribe(e=>events.push(e));mock.simulateRegistrations(n,ref.code);off();await db.$transaction(async tx=>{for(const _e of events)await add(tx,'referralEvent',{id:uid(),ambassadorId,studentRef:uid(),nickname:nickname((await tx.referralEvent.count())+1),type:'registered'});const review=await tx.pointsLedger.findFirst({where:{ambassadorId,refType:'review'},orderBy:{ts:'desc'}});const recent=await tx.referralEvent.findMany({where:{ambassadorId,...(review?{ts:{gt:review.ts}}:{})}});const flagged=fraudCheck(recent.map(r=>({ts:new Date(r.ts).toISOString(),nickname:r.nickname})));if(flagged&&!await tx.fraudFlag.findFirst({where:{ambassadorId,resolved:false}}))await add(tx,'fraudFlag',{id:uid(),ambassadorId,reason:'20+ registrations in 60 seconds / Всплеск регистраций за 60 секунд'});if(!flagged&&!await tx.fraudFlag.findFirst({where:{ambassadorId,resolved:false}}))await add(tx,'pointsLedger',{id:uid(),ambassadorId,delta:n,reason:'Referred registrations',refType:'referral',refId:uid()});});return {message:'Activity recorded. Check fraud queue / Активность записана. Проверьте очередь риска'};}
  if(op==='submitTask'){if(role!=='ambassador')throw new Error('Select ambassador role');await get(db,'ambassador',ambassadorId);const task=await get(db,'task',required(d,'taskId'));const proof=publicText(d,'proof');if(task.proofType==='number'&&!/^\d+$/.test(proof))throw new Error('Provide a count / Укажите число');if(task.proofType==='link'&&!/^https:\/\//.test(proof))throw new Error('Use an HTTPS proof link / Укажите HTTPS-ссылку');await add(db,'submission',{id:uid(),taskId:task.id,ambassadorId,proof,status:'pending'});return {message:'Submitted for review / Отправлено на проверку'};}
  if(op==='review'){if(role!=='admin')throw new Error('Select admin role');const status=choose(d,'status',['approved','rejected']);return db.$transaction(async tx=>{const s=await get(tx,'submission',required(d,'submissionId'));if(s.status!=='pending')throw new Error('Already reviewed / Уже рассмотрено');if(await tx.fraudFlag.findFirst({where:{ambassadorId:s.ambassadorId,resolved:false}}))throw new Error('Resolve fraud review before awarding points / Сначала рассмотрите флаг риска');const task=await get(tx,'task',s.taskId);await tx.submission.update({where:{id:s.id},data:{status,reviewedBy:'demo-admin'}});if(status==='approved')await add(tx,'pointsLedger',{id:uid(),ambassadorId:s.ambassadorId,delta:task.points,reason:task.title,refType:'submission',refId:s.id});return {message:'Review saved; level recalculated / Решение сохранено, уровень пересчитан'};});}
  if(op==='redeem'){if(role!=='ambassador')throw new Error('Select ambassador role');return db.$transaction(async tx=>{const reward=await get(tx,'reward',required(d,'rewardId'));const ledger=await tx.pointsLedger.findMany({where:{ambassadorId}});redeemBalance(balance(ledger as any),reward.costPoints,reward.stock);const id=uid();await add(tx,'redemption',{id,rewardId:reward.id,ambassadorId,status:'requested'});await add(tx,'pointsLedger',{id:uid(),ambassadorId,delta:-reward.costPoints,reason:reward.title,refType:'redemption',refId:id});await tx.reward.update({where:{id:reward.id},data:{stock:{decrement:1}}});return {message:'Reward requested / Награда заказана'};});}
  if(op==='resolve'){if(role!=='admin')throw new Error('Select admin role');await db.$transaction(async tx=>{const f=await get(tx,'fraudFlag',required(d,'flagId'));if(f.resolved)throw new Error('Already reviewed');await tx.fraudFlag.update({where:{id:f.id},data:{resolved:true}});await add(tx,'pointsLedger',{id:uid(),ambassadorId:f.ambassadorId,delta:0,reason:'Fraud review completed',refType:'review',refId:f.id});});return {message:'Flag reviewed. Future points resumed / Флаг рассмотрен. Новые начисления разрешены'};}
  if(op==='fulfill'){if(role!=='admin')throw new Error('Select admin role');await db.redemption.update({where:{id:required(d,'redemptionId')},data:{status:'fulfilled'}});return {message:'Fulfilled / Выдано'};}
  throw new Error('Unknown action');
 }
 async function ambassadorView(v:View){const ambassadors=await db.ambassador.findMany();const ledger=await db.pointsLedger.findMany();const events=await db.referralEvent.findMany();const selected=v.extra?.selection??'amb-0';const a=ambassadors.find(a=>a.id===selected)??ambassadors[0];const current=balance(ledger.filter(l=>l.ambassadorId===a.id) as any);const level=levelFor(current);v.metrics=[{label:'Баллы|Points',value:current},{label:'Уровень|Level',value:level.name,note:current<200?'До Silver:|Until Silver: '+(200-current):'Продолжайте создавать|Keep creating'},{label:'Регистрации|Registered',value:events.filter(e=>e.ambassadorId===a.id).length},{label:'Участники программы|Ambassadors',value:ambassadors.length}];
  if(v.path==='/join')v.forms.push({title:'Ваше влияние начинается здесь|Your impact starts here',op:'join',fields:[field('nickname','Публичный никнейм|Public nickname'),optionsCountry(),field('city','Город (без адреса)|City (no address)'),field('adult','Мне исполнилось 18 лет|I am at least 18','checkbox'),field('conduct','Принимаю правила: никакого сбора личных данных учеников|I accept the code of conduct: no student personal data','checkbox')]});
  else if(v.path==='/tasks'){const tasks=await db.task.findMany();v.cards=tasks.map(r=>({title:r.title,text:`${r.description}\n${r.points} points · ${r.proofType}`,tag:'✦'}));v.forms.push({title:'Подтвердите выполненное задание|Submit task proof',op:'submitTask',fields:[field('taskId','Задание (ID из таблицы)|Task ID','select',tasks.map(t=>t.id)),field('proof','Публичное подтверждение без личных данных|Public proof without personal data','textarea')],hidden:{ambassadorId:a.id}});v.tables.push({title:'Задания|Tasks',columns:['ID','Задание|Task','Баллы|Points','Формат|Proof format'],rows:tasks.map(t=>[t.id,t.title,t.points,t.proofType])});}
  else if(v.path==='/rewards'){const rewards=await db.reward.findMany();v.tables.push({title:'Награды|Rewards',columns:['ID','Название|Title','Стоимость|Cost','Осталось|Stock'],rows:rewards.map(r=>[r.id,r.title,r.costPoints,r.stock])});v.forms.push({title:'Выберите награду|Redeem a reward',op:'redeem',fields:[field('rewardId','Награда|Reward','select',rewards.map(r=>r.id))],hidden:{ambassadorId:a.id}});}
  else if(v.path==='/leaderboard'){const ranking=rank(ambassadors.map(a=>{const n=balance(ledger.filter(l=>l.ambassadorId===a.id) as any);return {...a,nickname:String(a.nickname),country:String(a.country),points:n,published:0,ts:new Date(a.createdAt).toISOString(),id:a.id};}));v.tables.push({title:'Глобальный рейтинг · фильтр по коду страны|Global ranking · filter by country code',columns:['#','Никнейм|Nickname','Страна|Country','Баллы|Points','Уровень|Level'],rows:ranking.map((a,i)=>[i+1,a.nickname,a.country,a.points,levelFor(a.points).name])});}
  else if(v.path==='/admin'){if(v.role!=='admin'){v.cards.push({title:'Нужна роль администратора|Admin role needed',text:'Выберите admin в меню ролей.|Select admin in the role menu.'});return;}const submissions=await db.submission.findMany();const flags=await db.fraudFlag.findMany();const redemptions=await db.redemption.findMany();v.tables.push({title:'Очередь заданий|Submission queue',columns:['ID','Участник|Ambassador','Задание|Task','Подтверждение|Proof','Статус|Status'],rows:submissions.map(s=>[s.id,s.ambassadorId,s.taskId,s.proof,s.status])},{title:'Флаги риска|Fraud flags',columns:['ID','Участник|Ambassador','Причина|Reason','Рассмотрен|Resolved'],rows:flags.map(f=>[f.id,f.ambassadorId,f.reason,String(f.resolved)])},{title:'Выдача наград|Redemptions',columns:['ID','Награда|Reward','Статус|Status'],rows:redemptions.map(r=>[r.id,r.rewardId,r.status])});const pending=submissions.filter(s=>s.status==='pending');if(pending.length)v.forms.push({title:'Рассмотреть задание|Review submission',op:'review',fields:[field('submissionId','Заявка|Submission','select',pending.map(s=>s.id)),field('status','Решение|Decision','select',['approved','rejected'])]});if(flags.some(f=>!f.resolved))v.forms.push({title:'Рассмотреть флаг|Resolve flag',op:'resolve',fields:[field('flagId','ID флага|Flag ID','select',flags.filter(f=>!f.resolved).map(f=>f.id))]});if(redemptions.some(r=>r.status==='requested'))v.forms.push({title:'Выдать награду|Fulfill reward',op:'fulfill',fields:[field('redemptionId','ID заказа|Redemption ID','select',redemptions.filter(r=>r.status==='requested').map(r=>r.id))]});}
  else{const link=await db.referralLink.findFirst({where:{ambassadorId:a.id}});v.title=`${a.nickname} · ${level.name}`;v.cards.push({title:'Ваша ссылка|Your referral',text:`/r/${link?.code}`,href:`/r/${link?.code}`,tag:'↗'},{title:'Код школы · демо|School code · demo',text:'START-001',tag:'◇'},{title:'Следующий уровень|Next level',text:current<200?`${current} / 200 · Silver`:`${current} points · ${level.name}`,tag:'✦'});v.tables.push({title:'Журнал баллов · только добавление|Append-only points ledger',columns:['Изменение|Delta','Причина|Reason','Дата|Date'],rows:ledger.filter(l=>l.ambassadorId===a.id).map(l=>[l.delta,l.reason,new Date(l.ts).toISOString().slice(0,10)])});v.extra={...v.extra,ambassadorId:a.id};}
 }

 async function challengeRanking(tx:Database,id:string):Promise<Row[]>{const c=await get(tx,'challenge',id);if(c.status==='closed'&&c.frozenJson)return JSON.parse(c.frozenJson);const teams=await tx.team.findMany({where:{challengeId:id}});const weights=JSON.parse(c.weightsJson);const rows:Row[]=[];for(const team of teams){const p=await tx.progressSnapshot.findFirst({where:{teamId:team.id},orderBy:{ts:'desc'}});const judges=await tx.judgeScore.findMany({where:{teamId:team.id}});const judge=judges.length?judges.reduce((n,s)=>n+s.total,0)/judges.length:0;rows.push({...team,points:challengeScore(p?.started??0,p?.published??0,p?.avgStage??0,judge,weights.auto),published:p?.published??0,ts:new Date(team.createdAt).toISOString()});}return rank(rows as any);}
 async function awardBadges(tx:Database,teamId:string){const snaps=await tx.progressSnapshot.findMany({where:{teamId},orderBy:{ts:'asc'}});const p=snaps.at(-1);const members=await tx.teamMember.findMany({where:{teamId}});const earned=badges({started:p?.started??0,published:p?.published??0,countries:members.map(m=>m.country),days:snaps.map(s=>new Date(s.ts).toISOString().slice(0,10))});for(const key of earned){if(!await tx.teamBadge.findFirst({where:{teamId,badgeId:key}}))await add(tx,'teamBadge',{id:uid(),teamId,badgeId:key});}}
 async function challengeMutate(op:string,d:Row,role:string){
  if(op==='createChallenge'){if(role!=='admin')throw new Error('Select admin role');const start=new Date(required(d,'startAt')),end=new Date(required(d,'endAt'));if(!Number.isFinite(+start)||!Number.isFinite(+end)||end<=start)throw new Error('End must follow start / Дата окончания должна быть позже начала');const rubric=required(d,'rubric').split(',').map(s=>s.trim());rubric.forEach(s=>assertPublic(s));const rw=required(d,'rubricWeights').split(',').map(Number);rubricScore(rubric.map(()=>50),rw);const id=uid();await add(db,'challenge',{id,title:publicText(d,'title'),theme:publicText(d,'theme'),startAt:start,endAt:end,status:'open',rubricJson:JSON.stringify(rubric),weightsJson:JSON.stringify({auto:number(d,'autoWeight',0,1),rubric:rw})});return {redirect:'/challenges/'+id};}
  if(op==='createTeam'){if(!['student','teacher','admin'].includes(role))throw new Error('Select student or teacher role');const c=await get(db,'challenge',required(d,'challengeId'));if(c.status!=='open')throw new Error('Challenge is not open / Набор закрыт');const code=required(d,'schoolCode');if(!(await platform.verifySchoolCode(code)).valid)throw new Error('Invalid school code / Проверьте код школы (демо: START-001)');const members=required(d,'members').split('\n').filter(Boolean).map(s=>{const [nick,country]=s.split(',').map(s=>s.trim());if(!countries.some(c=>c.code===country))throw new Error('Use nickname,ISO per line / Формат строки: никнейм,KZ');return {studentRef:uid(),nickname:nick,country};});validateTeam(members);const id=uid();await db.$transaction(async tx=>{await add(tx,'team',{id,challengeId:c.id,name:publicText(d,'name'),schoolCode:code,country:members[0].country});for(const m of members)await add(tx,'teamMember',{id:uid(),teamId:id,...m});await awardBadges(tx,id);});return {redirect:'/teams/'+id};}
  if(op==='simulate'){if(!['teacher','admin'].includes(role))throw new Error('Select teacher or admin role');const teams=await db.team.findMany();let advanced=0;for(const team of teams){const c=await get(db,'challenge',team.challengeId);if(c.status==='closed')continue;const members=await db.teamMember.findMany({where:{teamId:team.id}});const last=await db.progressSnapshot.findFirst({where:{teamId:team.id},orderBy:{ts:'desc'}});const published=Math.min(members.length,last?.published??0);const remainingStage=members.length>published?Math.min(9,Math.max(0,Math.round(((last?.avgStage??0)*members.length-published*10)/(members.length-published)))):10;const students=members.map((m,i)=>({studentRef:m.studentRef,nickname:m.nickname,schoolCode:team.schoolCode,stage:i<published?10:remainingStage,status:i<published?'published' as const:remainingStage>0?'started' as const:'none' as const}));const mock=new MockAiStartifyClient(students);mock.advanceSchool(team.schoolCode);const client:AiStartifyClient=mock;const progress=await client.listProgressBySchool(team.schoolCode);await add(db,'progressSnapshot',{id:uid(),teamId:team.id,started:progress.filter(s=>s.stage>0).length,published:progress.filter(s=>s.status==='published').length,avgStage:progress.reduce((n,s)=>n+s.stage,0)/progress.length,ts:new Date(Math.max(+now(),+(new Date(last?.ts??0))+86400000))});await awardBadges(db,team.id);advanced++;}return {message:`${advanced} teams advanced / команд продвинулись`};}
  if(op==='judge'){if(role!=='judge')throw new Error('Select judge role');const team=await get(db,'team',required(d,'teamId'));const c=await get(db,'challenge',team.challengeId);if(c.status==='closed')throw new Error('Results frozen / Результаты заморожены');const scores=required(d,'scores').split(',').map(Number);const w=JSON.parse(c.weightsJson);const total=rubricScore(scores,w.rubric);const judgeId=choose(d,'judgeId',['judge-0','judge-1','judge-2']);const old=await db.judgeScore.findFirst({where:{teamId:team.id,judgeId}});if(old)await db.judgeScore.update({where:{id:old.id},data:{criteriaJson:JSON.stringify(scores),total}});else await add(db,'judgeScore',{id:uid(),teamId:team.id,judgeId,criteriaJson:JSON.stringify(scores),total});return {message:'Leaderboard recalculated / Рейтинг пересчитан'};}
  if(op==='close'){if(role!=='admin')throw new Error('Select admin role');return db.$transaction(async tx=>{const c=await get(tx,'challenge',required(d,'challengeId'));if(c.status==='closed')throw new Error('Already closed');const ranking=await challengeRanking(tx,c.id);await tx.challenge.update({where:{id:c.id},data:{status:'closed',frozenJson:JSON.stringify(ranking)}});return {message:'Final results frozen / Итоги зафиксированы'};});}
  throw new Error('Unknown action');
 }
 async function challengeView(v:View){const challenges=await db.challenge.findMany();const teams=await db.team.findMany();const snaps=await db.progressSnapshot.findMany();v.metrics=[{label:'Челленджи|Challenges',value:challenges.length},{label:'Команды|Teams',value:teams.length},{label:'Снимки прогресса|Progress snapshots',value:snaps.length},{label:'Награды|Badges',value:await db.teamBadge.count()}];
  if(v.path.startsWith('/teams/')){const team=await get(db,'team',v.path.split('/')[2]);v.title=team.name;const members=await db.teamMember.findMany({where:{teamId:team.id}});const earned=await db.teamBadge.findMany({where:{teamId:team.id}});v.cards=earned.map(b=>({title:b.badgeId,text:'Заслужено командой|Earned together',tag:'✦'}));v.tables.push({title:'Команда|Team members',columns:['Никнейм|Nickname','Страна|Country'],rows:members.map(m=>[m.nickname,m.country])},{title:'История прогресса|Progress history',columns:['Дата|Date','Начаты|Started','Опубликованы|Published','Средний этап|Average stage'],rows:snaps.filter(s=>s.teamId===team.id).map(s=>[new Date(s.ts).toISOString().slice(0,10),s.started,s.published,s.avgStage.toFixed(1)])});}
  else if(v.path.startsWith('/challenges/')){const c=await get(db,'challenge',v.path.split('/')[2]);v.title=c.title;const ranking=await challengeRanking(db,c.id);v.cards=[{title:'Правила|Rules',text:`${c.theme}\n2–5 nicknames · 10 stages · ${JSON.parse(c.weightsJson).auto*100}% auto / ${(1-JSON.parse(c.weightsJson).auto)*100}% judge`,tag:'◇'},{title:'Даты|Timeline',text:`${new Date(c.startAt).toISOString().slice(0,10)} → ${new Date(c.endAt).toISOString().slice(0,10)}\n${c.status}`,tag:'◷'}];v.tables.push({title:'Рейтинг команд|Team leaderboard',columns:['#','Команда|Team','Страна|Country','Баллы|Score','Профиль|Profile'],rows:ranking.map((r,i)=>[i+1,r.name,r.country,r.points.toFixed(1),'/teams/'+r.id])});for(const key of ['schoolCode','country']){const grouped=new Map<string,number>();for(const r of ranking)grouped.set(r[key],(grouped.get(r[key])??0)+r.points);v.tables.push({title:key==='country'?'Страны|Countries':'Школы|Schools',columns:['Группа|Group','Баллы|Score'],rows:[...grouped].sort((a,b)=>b[1]-a[1]).map(([k,n])=>[k,n.toFixed(1)])});}if(c.status==='open')v.forms.push({title:'Создать команду|Create a team',op:'createTeam',hidden:{challengeId:c.id},fields:[field('name','Название команды|Team name'),field('schoolCode','Код школы|School code','text',undefined,'START-001'),{...field('members','2–5 строк: никнейм,страна|2–5 lines: nickname,country','textarea'),value:'Nova77,KZ\nOrbit88,UZ',hint:'Только никнеймы и ISO-код страны.|Nicknames and ISO country codes only.'}]});}
  else if(v.path==='/judge'){const active=teams.filter(t=>challenges.find(c=>c.id===t.challengeId)?.status!=='closed');v.forms.push({title:'Оценка по критериям|Score the rubric',op:'judge',fields:[field('teamId','Команда|Team','select',active.map(t=>t.id)),field('judgeId','Судья|Judge','select',['judge-0','judge-1','judge-2']),field('scores','Баллы 0–100 через запятую, по порядку критериев|Scores 0–100, comma-separated in rubric order','text',undefined,'80,75,90')]});v.tables.push({title:'Критерии челленджей|Challenge rubrics',columns:['Челлендж|Challenge','Критерии|Criteria','Веса|Weights'],rows:challenges.map(c=>[c.title,JSON.parse(c.rubricJson).join(', '),JSON.parse(c.weightsJson).rubric.join(', ')])});}
  else if(v.path==='/admin'){v.forms.push({title:'Новый челлендж|Create a challenge',op:'createChallenge',fields:[field('title','Название|Title'),field('theme','Тема|Theme'),field('startAt','Начало|Start','date',undefined,'2026-11-14'),field('endAt','Окончание|End','date',undefined,'2027-02-01'),field('rubric','Критерии через запятую|Comma-separated criteria','text',undefined,'impact,originality,feasibility'),field('rubricWeights','Веса критериев|Rubric weights','text',undefined,'0.4,0.3,0.3'),field('autoWeight','Доля автоматического балла 0–1|Auto score weight 0–1','number',undefined,.5)]});v.forms.push({title:'Зафиксировать результаты|Close and freeze results',op:'close',fields:[field('challengeId','Челлендж|Challenge','select',challenges.filter(c=>c.status!=='closed').map(c=>c.id))]});}
  else if(v.path==='/showcase'){for(const c of challenges.filter(c=>c.status==='closed'))for(const r of (await challengeRanking(db,c.id)).slice(0,3))v.cards.push({title:r.name,text:`${c.title}\n${r.country} · ${r.points.toFixed(1)} points`,href:'/teams/'+r.id,tag:'✦'});}
  else{v.cards=challenges.map(c=>({title:c.title,text:`${c.theme}\n${c.status} · ${Math.max(0,Math.ceil((+new Date(c.endAt)-Date.now())/86400000))} days / дней`,href:'/challenges/'+c.id,tag:c.status}));}
 }

 async function schoolStudents(tx:Database,id:string){const classes=await tx.classGroup.findMany({where:{schoolId:id}});return tx.studentEntry.findMany({where:{classId:{in:classes.map(c=>c.id)}}});}
 async function portalMutate(op:string,d:Row,role:string){
  if(op==='registerSchool'){if(role!=='teacher')throw new Error('Select teacher role');const id=uid(),consent=d.consent==='true';await add(db,'school',{id,name:publicText(d,'name'),country:choose(d,'country',countries.map(c=>c.code)),city:publicText(d,'city'),type:choose(d,'type',['secondary','club','other']),status:consent?'pilot':'lead',consentConfirmed:consent});return {redirect:'/dashboard?selection='+id,message:'School registered / Школа добавлена'};}
  if(op==='partnerUpdate'){if(role!=='partner-manager')throw new Error('Select partner-manager role');const id=required(d,'schoolId');await get(db,'school',id);const status=choose(d,'status',['lead','pilot','active','paused']);await db.$transaction(async tx=>{const s=await tx.school.update({where:{id},data:{status}});await tx.classGroup.updateMany({where:{schoolId:id},data:{active:codeActive(s.consentConfirmed,status)}});if(String(d.note??'').trim())await add(tx,'partnerNote',{id:uid(),schoolId:id,note:publicText(d,'note')});});return {message:'Pipeline updated / Статус школы обновлён'};}
  if(role!=='teacher')throw new Error('Select teacher role');
  if(op==='consent'){const id=required(d,'schoolId');if(d.consent!=='true')throw new Error('Confirm parental consent / Подтвердите согласие родителей');await db.$transaction(async tx=>{const s=await tx.school.update({where:{id},data:{consentConfirmed:true}});await tx.classGroup.updateMany({where:{schoolId:id},data:{active:codeActive(true,s.status)}});});return {message:'Consent recorded; eligible codes activated / Согласие записано, доступные коды активированы'};}
  if(op==='createClass'){const s=await get(db,'school',required(d,'schoolId'));const id=uid();await add(db,'classGroup',{id,schoolId:s.id,name:publicText(d,'name'),gradeRange:publicText(d,'gradeRange'),code:'CLUB-'+id.slice(0,8).toUpperCase(),active:codeActive(s.consentConfirmed,s.status)});return {redirect:'/classes/'+id};}
  if(op==='import'){const c=await get(db,'classGroup',required(d,'classId'));const s=await get(db,'school',c.schoolId);if(!c.active||!s.consentConfirmed)throw new Error('Confirm parental consent before importing / Перед импортом подтвердите согласие родителей');const parsed=parseNicknameCsv(required(d,'csv'));if(parsed.errors.length)throw new Error(parsed.errors.map(e=>`Row / Строка ${e.row}: ${e.message}`).join('\n'));if(!parsed.valid.length)throw new Error('No nicknames / Нет никнеймов');const existing=await db.studentEntry.findMany({where:{classId:c.id}});if(parsed.valid.some(n=>existing.some(e=>e.nickname===n)))throw new Error('Nickname already in class / Никнейм уже есть в классе');await db.$transaction(async tx=>{for(const nick of parsed.valid)await add(tx,'studentEntry',{id:uid(),classId:c.id,nickname:nick,studentRef:uid(),stage:0,status:'none'});});return {message:`${parsed.valid.length} nicknames imported / никнеймов добавлено`};}
  if(op==='simulate'){const classes=await db.classGroup.findMany({where:{active:true}});for(const c of classes){const s=await get(db,'school',c.schoolId);if(!codeActive(s.consentConfirmed,s.status))continue;const entries=await db.studentEntry.findMany({where:{classId:c.id}});const mock=new MockAiStartifyClient(entries.map(e=>({studentRef:e.studentRef,nickname:e.nickname,schoolCode:c.code,stage:e.stage,status:e.status})));mock.advanceSchool(c.code);const client:AiStartifyClient=mock;for(const p of await client.listProgressBySchool(c.code))await db.studentEntry.update({where:{studentRef:p.studentRef},data:{stage:p.stage,status:p.status}});}return {message:'Class progress synchronized from demo adapter / Прогресс классов обновлён через демоадаптер'};}
  if(op==='report'){const s=await get(db,'school',required(d,'schoolId'));const period=required(d,'period');if(!/^\d{4}-\d{2}$/.test(period))throw new Error('Use YYYY-MM / Формат ГГГГ-ММ');const entries=await schoolStudents(db,s.id);await add(db,'report',{id:uid(),schoolId:s.id,period,dataJson:JSON.stringify(entries.map(e=>({nickname:e.nickname,stage:e.stage,status:e.status})))});return {message:'Current progress snapshot saved for selected period / Снимок текущего прогресса сохранён за выбранный период'};}
  throw new Error('Unknown action');
 }
 async function portalView(v:View){const schools=await db.school.findMany();const owning=v.path.startsWith('/classes/')?await get(db,'classGroup',v.path.split('/')[2]):null;const selected=schools.find(s=>s.id===(owning?.schoolId??v.extra?.selection))??schools[0];const classes=await db.classGroup.findMany({where:{schoolId:selected.id}});const students=await schoolStudents(db,selected.id);const health=activationHealth(students as any);v.metrics=[{label:'Школы|Schools',value:schools.length},{label:'Ученики школы|School students',value:health.total},{label:'Начаты|Started',value:health.started},{label:'Опубликованы|Published',value:health.published},{label:'Баллы школы|School points',value:points(health.started,health.published)},{label:'Активация|Activation',value:Math.round(100*health.startedShare)+'%'}];v.extra={...v.extra,selection:selected.id};
  if(v.path==='/register')v.forms.push({title:'Откройте клуб в вашей школе|Bring a club to your school',op:'registerSchool',fields:[field('name','Название школы|School name'),optionsCountry(),field('city','Город (без адреса)|City (no address)'),field('type','Тип|Type','select',['secondary','club','other']),{...field('consent','Подтверждаю, что школа собрала согласия родителей|I confirm the school has collected parental consent','checkbox'),required:false}]});
  else if(v.path.startsWith('/classes/')){const c=await get(db,'classGroup',v.path.split('/')[2]);const roster=await db.studentEntry.findMany({where:{classId:c.id}});v.title=c.name;v.cards.push({title:'Код класса|Class code',text:c.active?`${c.code}\nПрисоединяйтесь к клубу с учителем.|${c.code}\nJoin the startup club with your teacher.`:'Код неактивен. Подтвердите согласие родителей в обзоре школы.|Code inactive. Confirm parental consent on the school dashboard.',tag:c.active?'✓':'◇'});v.tables.push({title:'Прогресс по никнеймам|Nickname roster',columns:['Никнейм|Nickname','Этап 0–10|Stage 0–10','Прогресс|Progress','Статус|Status'],rows:roster.map(e=>[e.nickname,e.stage,'●'.repeat(e.stage)+'○'.repeat(10-e.stage),e.status])});v.forms.push({title:'Импорт CSV с никнеймами|Import nickname CSV',op:'import',hidden:{classId:c.id},fields:[{...field('csv','Один никнейм в строке, заголовок nickname необязателен|One nickname per line, optional nickname header','textarea'),value:'nickname\nOrbit42\nComet77',hint:'Email, телефоны и ФИО отклоняются с номерами строк.|Emails, phones and full names are rejected with row numbers.'}]});}
  else if(v.path==='/lesson-kit'){v.cards=(await db.lessonKit.findMany({orderBy:{order:'asc'}})).map(l=>({title:`${l.order}. ${l.title}`,text:`${l.objectives.split('|')[0]}\n${l.steps.split('|')[0]}\nЭтапы ${l.stageRange} · 45 минут|${l.objectives.split('|')[1]}\n${l.steps.split('|')[1]}\nStages ${l.stageRange} · 45 minutes`,tag:String(l.order)}));}
  else if(v.path==='/partner'){if(v.role!=='partner-manager'){v.cards.push({title:'Вид менеджера партнёрств|Partner manager view',text:'Выберите partner-manager в меню ролей.|Select partner-manager in the role menu.'});return;}v.chart=['lead','pilot','active','paused'].map(label=>({label,value:schools.filter(s=>s.status===label).length}));const rows=[];for(const s of schools){const h=activationHealth(await schoolStudents(db,s.id) as any);rows.push([s.id,s.name,s.country,s.status,Math.round(100*h.startedShare)+'%',Math.round(100*h.publishedShare)+'%']);}v.tables.push({title:'Партнёрские школы|School pipeline',columns:['ID','Школа|School','Страна|Country','Статус|Status','Начали|Started','Опубликовали|Published'],rows});v.forms.push({title:'Обновить статус и заметку|Update status and note',op:'partnerUpdate',fields:[field('schoolId','Школа|School','select',schools.map(s=>s.id)),field('status','Статус|Status','select',['lead','pilot','active','paused']),{...field('note','Заметка без персональных данных|Note without personal data','textarea'),required:false}]});const notes=await db.partnerNote.findMany();v.tables.push({title:'Заметки|Notes',columns:['Школа|School','Заметка|Note'],rows:notes.map(n=>[n.schoolId,n.note])});}
  else if(v.path==='/reports'){v.forms.push({title:'Сохранить текущий снимок прогресса|Save current progress snapshot',op:'report',hidden:{schoolId:selected.id},fields:[field('period','Период отчёта|Report period','month',undefined,'2026-11')]});const reports=await db.report.findMany({where:{schoolId:selected.id}});v.tables.push({title:'Сохранённые отчёты|Saved reports',columns:['Период|Period','Создан|Generated','CSV'],rows:reports.map(r=>[r.period,new Date(r.generatedAt).toISOString().slice(0,10),'/api/export?report='+r.id])});v.tables.push({title:'Текущий прогресс|Current progress',columns:['Никнейм|Nickname','Этап|Stage','Статус|Status'],rows:students.map(s=>[s.nickname,s.stage,s.status])});}
  else{v.title=selected.name;v.cards.push({title:'Следующее занятие|Next best action',text:`${health.total-health.started} учеников ещё не начали. Проведите занятие 1.|${health.total-health.started} students have not started. Run lesson 1.`,href:'/lesson-kit',tag:'↗'});v.tables.push({title:'Классы школы|School classes',columns:['Класс|Class','Возрастная группа|Grade range','Код|Code','Открыть|Open'],rows:classes.map(c=>[c.name,c.gradeRange,c.active?c.code:'inactive','/classes/'+c.id])});if(!selected.consentConfirmed)v.forms.push({title:'Активировать коды|Activate class codes',op:'consent',hidden:{schoolId:selected.id},fields:[field('consent','Школа собрала согласия родителей|The school has collected parental consent','checkbox')]});v.forms.push({title:'Создать класс|Create a class',op:'createClass',hidden:{schoolId:selected.id},fields:[field('name','Название класса|Class name'),field('gradeRange','Классы обучения|Grade range','text',undefined,'7–11')]});v.cards.push(...schools.map(s=>({title:s.name,text:`${s.country} · ${s.status}`,href:'/dashboard?selection='+s.id,tag:'◇'})));}
 }

 async function activeSeason(tx:Database){const s=await tx.season.findFirst({where:{active:true}});if(!s)throw new Error('No active season / Нет активного сезона');return s;}
 async function leagueRanking(tx:Database,seasonId?:string){const season=seasonId?await get(tx,'season',seasonId):await activeSeason(tx);const schools=await tx.school.findMany();const snaps=await tx.pointsSnapshot.findMany({where:{seasonId:season.id}});return rank(schools.map(s=>{const snap=snaps.find(p=>p.schoolId===s.id);return {id:String(s.id),name:String(s.name),country:String(s.country),city:String(s.city),slug:String(s.slug),started:snap?.started??0,published:snap?.published??0,points:points(snap?.started??0,snap?.published??0),ts:new Date(snap?.ts??season.startAt).toISOString()};}));}
 async function leagueMutate(op:string,d:Row,role:string){
  if(op==='joinSchool'){const code=required(d,'schoolCode');if(!(await platform.verifySchoolCode(code)).valid)throw new Error('Invalid school code. Try START-001 / Неверный код школы. Демо: START-001');const s=await db.school.findUnique({where:{code}});if(!s)throw new Error('School not available in this demo');return {redirect:'/?selection='+s.id};}
  if(op==='publish'){if(!['student','teacher'].includes(role))throw new Error('Select student or teacher role / Выберите роль ученика или учителя');const schoolId=required(d,'schoolId');const s=await get(db,'school',schoolId);if(!(await platform.verifySchoolCode(s.code)).valid)throw new Error('Invalid school code');const nick=publicText(d,'nickname'),title=publicText(d,'title'),idea=publicText(d,'idea');if(nick.length>40||title.length>60||idea.length>160)throw new Error('Use at most 40/60/160 characters for nickname/title/idea / Максимум 40/60/160 символов для никнейма/названия/идеи');return db.$transaction(async tx=>{const season=await activeSeason(tx);if(season.frozen)throw new Error('Season frozen. Ask a teacher to start a new season / Сезон заморожен. Учитель может начать новый');const id=uid(),projectId=uid();await add(tx,'student',{id,schoolId,nickname:nick,studentRef:uid()});await add(tx,'project',{id:projectId,studentId:id,title,idea,status:'published',passportId:'DEMO-'+projectId.slice(0,8),publishedAt:now()});const snap=await tx.pointsSnapshot.findFirst({where:{seasonId:season.id,schoolId}});if(snap)await tx.pointsSnapshot.update({where:{id:snap.id},data:{started:{increment:1},published:{increment:1},points:{increment:points(1,1)}}});else await add(tx,'pointsSnapshot',{id:`${season.id}:${schoolId}`,seasonId:season.id,schoolId,started:1,published:1,points:points(1,1)});return {redirect:'/card?selection='+schoolId,message:'Published. League rankings updated / Опубликовано. Рейтинг обновлён'};});}
  if(role!=='teacher')throw new Error('Select teacher role / Выберите роль учителя');
  if(op==='freeze'){const season=await activeSeason(db);await db.season.update({where:{id:season.id},data:{frozen:true}});return {message:'Season frozen; history retained / Сезон заморожен, история сохранена'};}
  if(op==='newSeason'){const title=publicText(d,'title');return db.$transaction(async tx=>{await tx.season.updateMany({where:{active:true},data:{active:false,frozen:true}});const id=uid();await add(tx,'season',{id,title,startAt:now(),endAt:new Date(Date.now()+90*86400000),active:true,frozen:false});for(const s of await tx.school.findMany())await add(tx,'pointsSnapshot',{id:`${id}:${s.id}`,seasonId:id,schoolId:s.id,started:0,published:0,points:0});return {message:'New season started; past standings preserved / Новый сезон начат, прошлые результаты сохранены'};});}
  if(op==='simulate'){return db.$transaction(async tx=>{const season=await activeSeason(tx);if(season.frozen)throw new Error('Season frozen / Сезон заморожен');const n=number(d,'n',1,100);const students=await tx.student.findMany({take:n});for(let i=0;i<students.length;i++){const s=students[i];const mock=new MockAiStartifyClient([{studentRef:s.studentRef,nickname:s.nickname,schoolCode:'demo',stage:i%2?9:0,status:'started'}]);mock.advanceSchool('demo');const client:AiStartifyClient=mock;const p=await client.getProgress(s.studentRef);const published=p?.status==='published';const snapshot=await tx.pointsSnapshot.findFirst({where:{seasonId:season.id,schoolId:s.schoolId}});if(!snapshot)continue;await tx.pointsSnapshot.update({where:{id:snapshot.id},data:{started:{increment:1},published:{increment:published?1:0},points:{increment:points(1,published?1:0)}}});await add(tx,'project',{id:uid(),studentId:s.id,title:'demo-orbit',idea:'A small idea for a better school / Идея для школы',status:published?'published':'started',passportId:'DEMO-SIM',publishedAt:published?now():null});}return {message:'League progress updated / Прогресс лиги обновлён'};});}
  throw new Error('Unknown action');
 }
 async function leagueView(v:View){const season=await activeSeason(db);const ranking=await leagueRanking(db);const selected=ranking.find(s=>s.id===v.extra?.selection)??ranking[0];v.extra={...v.extra,selection:selected.id};v.metrics=[{label:'Школы|Schools',value:ranking.length},{label:'Начаты|Started',value:ranking.reduce((n,s)=>n+s.started,0)},{label:'Опубликованы|Published',value:ranking.reduce((n,s)=>n+s.published,0)},{label:'Баллы вашей школы|Your school points',value:selected.points}];v.cards.push({title:season.title,text:`${new Date(season.startAt).toISOString().slice(0,10)} → ${new Date(season.endAt).toISOString().slice(0,10)}\n${season.frozen?'Заморожен|Frozen':'Активный сезон|Active season'}`,tag:'⚑'});
  if(v.path==='/join')v.forms.push({title:'Найдите вашу школу|Find your school',op:'joinSchool',fields:[field('schoolCode','Код школы|School code','text',undefined,'START-001')]});
  else if(v.path==='/card'){const students=await db.student.findMany({where:{schoolId:selected.id}});const p=await db.project.findFirst({where:{studentId:{in:students.map(s=>s.id)},status:'published'},orderBy:{createdAt:'desc'}});if(p){const student=students.find(s=>s.id===p.studentId);const s=await get(db,'school',selected.id);v.extra={...v.extra,project:{...p,nickname:student?.nickname,school:s.name,country:s.country,code:s.code}};}v.forms.push({title:'Опубликуйте карточку основателя|Publish your founder card',op:'publish',hidden:{schoolId:selected.id},button:'Опубликовать и обновить рейтинг|Publish and update league',fields:[{...field('nickname','Никнейм (до 40 символов)|Nickname (up to 40 characters)'),value:'Nova42'},field('title','Название проекта (до 60 символов)|Project title (up to 60 characters)','text',undefined,'eco orbit'),field('idea','Идея в одной строке (до 160 символов)|One-line idea (up to 160 characters)','textarea',undefined,'a greener playground')]});v.cards.push({title:'Ваша школа|Your school',text:`${selected.name} · ${selected.country}`,href:'/?selection='+selected.id,tag:'↗'});}
  else if(v.path.startsWith('/schools/')){const s=await db.school.findUnique({where:{slug:v.path.split('/')[2]}});if(!s)throw new Error('School not found');v.title=s.name;const students=await db.student.findMany({where:{schoolId:s.id}});const projects=await db.project.findMany({where:{studentId:{in:students.map(s=>s.id)},status:'published'}});v.cards.push(...projects.slice(0,20).map(p=>({title:p.title,text:`${students.find(s=>s.id===p.studentId)?.nickname} · ${s.country}\n${p.idea}`,tag:'✦'})));const history=await db.pointsSnapshot.findMany({where:{schoolId:s.id}});v.tables.push({title:'История сезонов|Season history',columns:['Сезон|Season','Начаты|Started','Опубликованы|Published','Баллы|Points'],rows:history.map(p=>[p.seasonId,p.started,p.published,p.points])});}
  else if(v.path==='/admin'){v.forms.push({title:'Начать новый сезон|Start a new season',op:'newSeason',fields:[field('title','Название сезона|Season title','text',undefined,'next orbit')]},{title:'Зафиксировать текущий сезон|Freeze current season',op:'freeze',fields:[]});const seasons=await db.season.findMany();v.tables.push({title:'Сезоны|Seasons',columns:['Название|Title','Активен|Active','Заморожен|Frozen'],rows:seasons.map(s=>[s.title,String(s.active),String(s.frozen)])});}
  else{v.tables.push({title:'Школы|Schools',columns:['#','Школа|School','Страна|Country','Начаты|Started','Опубликованы|Published','Баллы|Points','Профиль|Profile'],rows:ranking.map((r,i)=>[i+1,r.id===selected.id?'★ '+r.name:r.name,r.country,r.started,r.published,r.points,'/schools/'+r.slug])});for(const key of ['country','city'] as const){const groups=new Map<string,{points:number;published:number;started:number;ts:string;id:string}>();for(const r of ranking){const g=groups.get(r[key])??{points:0,published:0,started:0,ts:r.ts,id:r[key]};groups.set(r[key],{...g,points:g.points+r.points,published:g.published+r.published,started:g.started+r.started,ts:g.ts<r.ts?g.ts:r.ts});}v.tables.push({title:key==='country'?'Страны|Countries':'Города|Cities',columns:['#','Название|Name','Начаты|Started','Опубликованы|Published','Баллы|Points'],rows:rank([...groups.values()]).map((r,i)=>[i+1,r.id,r.started,r.published,r.points])});}}
 }

 async function mutate(op:string,d:Row,role=roles[0]):Promise<Row>{if(app==='growth-engine')return growthMutate(op,d,role);
 if(app==='ambassador-platform')return ambassadorMutate(op,d,role);
 if(app==='challenge-platform')return challengeMutate(op,d,role);
 if(app==='school-portal')return portalMutate(op,d,role);
 if(app==='school-league')return leagueMutate(op,d,role);
 // APP_MUTATIONS
 throw new Error('Unknown action');}
 async function view(path:string,role=roles[0],selection?:string):Promise<View>{const v:View={app,path,role,roles,title:names[app],subtitle:'От идеи к глобальному движению|From an idea to a global movement',extra:{selection},nav:menus[app].map(([href,label])=>({href,label})),metrics:[],tables:[],forms:[],cards:[]};if(app==='growth-engine')await growthView(v);
 if(app==='ambassador-platform')await ambassadorView(v);
 if(app==='challenge-platform')await challengeView(v);
 if(app==='school-portal')await portalView(v);
 if(app==='school-league')await leagueView(v);
 // APP_VIEWS
 return JSON.parse(JSON.stringify(v));}
 async function exportCsv(reportId?:string){if(app==='growth-engine'){const rows=await db.campaign.findMany();const links=await db.referralLink.findMany();const events=await db.trackedEvent.findMany();return csv(rows.map(c=>{const code=links.find(l=>l.campaignId===c.id)?.code;const f=funnel(events.filter(e=>e.linkCode===code) as any);return {campaign:c.name,country:c.country,channel:c.channel,...f,cpaRegistration:cpa(c.budgetUsd,f.registered),cpaPublished:cpa(c.budgetUsd,f.published)};}));}
 if(app==='ambassador-platform')return csv(await db.pointsLedger.findMany());
 if(app==='challenge-platform')return csv(await challengeRanking(db,'challenge-0'));
 if(app==='school-portal'){if(reportId){const r=await get(db,'report',reportId);return csv(JSON.parse(r.dataJson));}return csv((await db.studentEntry.findMany()).map(s=>({nickname:s.nickname,stage:s.stage,status:s.status})));}
 if(app==='school-league')return csv(await leagueRanking(db));
 // APP_EXPORTS
 return csv([]);}
 async function visit(code:string){if(!db.referralLink)throw new Error('Unavailable');const l=await db.referralLink.findUnique({where:{code}});if(!l)throw new Error('Unknown link');if(app==='growth-engine'){const c=await get(db,'campaign',l.campaignId);await add(db,'trackedEvent',{id:uid(),linkCode:code,type:'visit',country:c.country});}}
 return {roles,seed,mutate,view,exportCsv,visit};
}
